'use strict';

const EQUAL = 0;
const DELETE = 1;
const INSERT = 2;
const OP_NAMES = ['equal', 'delete', 'insert'];

/**
 * Return an edit script of { op: 'equal' | 'delete' | 'insert', line: string }.
 * a and b are arrays of strings; lines are compared by exact string equality.
 * Reading equal/delete entries reconstructs a; equal/insert reconstructs b.
 * Equal entries must form a longest common subsequence: the number of deletes
 * plus inserts equals a.length + b.length - 2 * LCS(a, b).
 * Results must be deterministic. In every maximal region without an equal
 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  return editScript(a, b).map((e) => ({ op: OP_NAMES[e.op], line: e.line }));
}

/**
 * Internal edit script with numeric ops; deletes precede inserts in every
 * maximal non-equal region.
 */
function editScript(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b)) {
    throw new TypeError('diffLines expects two arrays of strings');
  }
  const n = a.length;
  const m = b.length;

  // Intern lines so the inner loops compare integers.
  const ids = new Map();
  const A = new Int32Array(n);
  const B = new Int32Array(m);
  for (let i = 0; i < n; i++) A[i] = intern(ids, a[i]);
  for (let j = 0; j < m; j++) B[j] = intern(ids, b[j]);

  // Raw ops in path order; each entry is [op, index into a or b].
  const raw = [];
  myers(A, B, 0, n, 0, m, raw);

  // Normalize: within each maximal non-equal region, deletes before inserts.
  const out = [];
  let dels = [];
  let ins = [];
  const flush = () => {
    for (const i of dels) out.push({ op: DELETE, line: a[i] });
    for (const j of ins) out.push({ op: INSERT, line: b[j] });
    dels = [];
    ins = [];
  };
  for (const [op, idx] of raw) {
    if (op === EQUAL) {
      if (dels.length || ins.length) flush();
      out.push({ op: EQUAL, line: a[idx] });
    } else if (op === DELETE) {
      dels.push(idx);
    } else {
      ins.push(idx);
    }
  }
  flush();
  return out;
}

function intern(ids, line) {
  let id = ids.get(line);
  if (id === undefined) {
    id = ids.size;
    ids.set(line, id);
  }
  return id;
}

/**
 * Linear-space Myers diff of A[aLo, aHi) against B[bLo, bHi), appending ops to
 * out in order. Recurses on the middle snake, so each half is minimal and the
 * split lies on an optimal path.
 */
function myers(A, B, aLo, aHi, bLo, bHi, out) {
  // Common prefix.
  while (aLo < aHi && bLo < bHi && A[aLo] === B[bLo]) {
    out.push([EQUAL, aLo]);
    aLo++;
    bLo++;
  }
  // Common suffix (emitted after the middle).
  let suffix = 0;
  while (aLo < aHi - suffix && bLo < bHi - suffix && A[aHi - suffix - 1] === B[bHi - suffix - 1]) {
    suffix++;
  }
  const aEnd = aHi - suffix;
  const bEnd = bHi - suffix;

  if (aLo === aEnd) {
    for (let j = bLo; j < bEnd; j++) out.push([INSERT, j]);
  } else if (bLo === bEnd) {
    for (let i = aLo; i < aEnd; i++) out.push([DELETE, i]);
  } else {
    const [x, y] = middleSnake(A, B, aLo, aEnd, bLo, bEnd);
    myers(A, B, aLo, aLo + x, bLo, bLo + y, out);
    myers(A, B, aLo + x, aEnd, bLo + y, bEnd, out);
  }

  for (let s = 0; s < suffix; s++) out.push([EQUAL, aEnd + s]);
}

/**
 * Find a split point (x, y), relative to (aLo, bLo), on a shortest edit path
 * between nonempty ranges whose first and last elements differ.
 */
function middleSnake(A, B, aLo, aHi, bLo, bHi) {
  const N = aHi - aLo;
  const M = bHi - bLo;
  const maxD = Math.ceil((N + M) / 2);
  const vOffset = maxD;
  const vLength = 2 * maxD + 2;
  const v1 = new Int32Array(vLength).fill(-1);
  const v2 = new Int32Array(vLength).fill(-1);
  v1[vOffset + 1] = 0;
  v2[vOffset + 1] = 0;
  const delta = N - M;
  // With odd delta the forward path detects overlap; with even, the reverse.
  const front = (delta & 1) !== 0;
  let k1start = 0;
  let k1end = 0;
  let k2start = 0;
  let k2end = 0;

  for (let d = 0; d < maxD; d++) {
    for (let k1 = -d + k1start; k1 <= d - k1end; k1 += 2) {
      const k1Off = vOffset + k1;
      let x1;
      if (k1 === -d || (k1 !== d && v1[k1Off - 1] < v1[k1Off + 1])) {
        x1 = v1[k1Off + 1];
      } else {
        x1 = v1[k1Off - 1] + 1;
      }
      let y1 = x1 - k1;
      while (x1 < N && y1 < M && A[aLo + x1] === B[bLo + y1]) {
        x1++;
        y1++;
      }
      v1[k1Off] = x1;
      if (x1 > N) {
        k1end += 2; // Ran off the right edge.
      } else if (y1 > M) {
        k1start += 2; // Ran off the bottom edge.
      } else if (front) {
        const k2Off = vOffset + delta - k1;
        if (k2Off >= 0 && k2Off < vLength && v2[k2Off] !== -1) {
          const x2 = N - v2[k2Off];
          if (x1 >= x2) return [x1, y1];
        }
      }
    }

    for (let k2 = -d + k2start; k2 <= d - k2end; k2 += 2) {
      const k2Off = vOffset + k2;
      let x2;
      if (k2 === -d || (k2 !== d && v2[k2Off - 1] < v2[k2Off + 1])) {
        x2 = v2[k2Off + 1];
      } else {
        x2 = v2[k2Off - 1] + 1;
      }
      let y2 = x2 - k2;
      while (x2 < N && y2 < M && A[aHi - x2 - 1] === B[bHi - y2 - 1]) {
        x2++;
        y2++;
      }
      v2[k2Off] = x2;
      if (x2 > N) {
        k2end += 2;
      } else if (y2 > M) {
        k2start += 2;
      } else if (!front) {
        const k1Off = vOffset + delta - k2;
        if (k1Off >= 0 && k1Off < vLength && v1[k1Off] !== -1) {
          const x1 = v1[k1Off];
          const y1 = vOffset + x1 - k1Off;
          if (x1 >= N - x2) return [x1, y1];
        }
      }
    }
  }
  // Unreachable for nonempty ranges: the paths must meet within maxD steps.
  throw new Error('diff: middle snake not found');
}

/**
 * Return unified hunks: [{ oldStart, oldLines, newStart, newLines, lines }].
 * context is a nonnegative integer, default 3. Hunk lines are original strings
 * prefixed with ' ' (equal), '-' (delete), or '+' (insert); remove exactly one
 * prefix to recover a line, even when the original starts with a prefix itself.
 * oldLines counts context + deletes; newLines counts context + inserts.
 * Include up to context unchanged lines before/after each changed region.
 * Merge regions if the intervening unchanged gap is <= 2 * context (their
 * context would touch or overlap). Do not duplicate context in merged hunks.
 * Starts are 1-based, except a zero-line range names the line BEFORE the range:
 * oldLines === 0 uses the preceding old line number (0 for insertion at top),
 * and newLines === 0 uses the preceding new line number (0 for deletion at top).
 * Coordinates refer to the complete original a and result b, not a local hunk.
 * Identical inputs return []. Use diffLines' minimality and deletion ordering.
 * Neither input may be mutated. Inputs follow the diffLines contract.
 */
function unifiedHunks(a, b, { context = 3 } = {}) {
  if (!Number.isInteger(context) || context < 0) {
    throw new RangeError('context must be a nonnegative integer');
  }
  const script = editScript(a, b);
  const len = script.length;

  // Old/new line counts consumed before each script index.
  const oldBefore = new Int32Array(len + 1);
  const newBefore = new Int32Array(len + 1);
  for (let i = 0; i < len; i++) {
    const op = script[i].op;
    oldBefore[i + 1] = oldBefore[i] + (op === INSERT ? 0 : 1);
    newBefore[i + 1] = newBefore[i] + (op === DELETE ? 0 : 1);
  }

  // Maximal changed regions as [start, end) script indices.
  const regions = [];
  for (let i = 0; i < len; ) {
    if (script[i].op === EQUAL) {
      i++;
      continue;
    }
    const start = i;
    while (i < len && script[i].op !== EQUAL) i++;
    regions.push([start, i]);
  }

  const hunks = [];
  for (let r = 0; r < regions.length; ) {
    const first = regions[r];
    let last = first;
    r++;
    // Gap between regions consists solely of equal entries.
    while (r < regions.length && regions[r][0] - last[1] <= 2 * context) {
      last = regions[r];
      r++;
    }
    const from = Math.max(0, first[0] - context);
    const to = Math.min(len, last[1] + context);

    const lines = [];
    for (let i = from; i < to; i++) {
      const { op, line } = script[i];
      lines.push((op === EQUAL ? ' ' : op === DELETE ? '-' : '+') + line);
    }
    const oldLines = oldBefore[to] - oldBefore[from];
    const newLines = newBefore[to] - newBefore[from];
    hunks.push({
      oldStart: oldLines === 0 ? oldBefore[from] : oldBefore[from] + 1,
      oldLines,
      newStart: newLines === 0 ? newBefore[from] : newBefore[from] + 1,
      newLines,
      lines,
    });
  }
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  if (!Array.isArray(a)) throw new TypeError('applyHunks expects an array of lines');
  if (!Array.isArray(hunks)) throw new TypeError('applyHunks expects an array of hunks');

  const out = [];
  let cursor = 0; // Next unconsumed index into a.

  for (let h = 0; h < hunks.length; h++) {
    const fail = (why) => {
      throw new Error(`hunk ${h} does not apply: ${why}`);
    };
    const hunk = hunks[h];
    if (hunk === null || typeof hunk !== 'object') fail('not an object');
    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
    if (!Array.isArray(lines)) fail('lines is not an array');
    for (const n of [oldStart, oldLines, newStart, newLines]) {
      if (!Number.isInteger(n) || n < 0) fail('coordinates must be nonnegative integers');
    }

    let olds = 0;
    let news = 0;
    for (const l of lines) {
      if (typeof l !== 'string' || l.length === 0) fail('malformed line');
      const p = l[0];
      if (p === ' ') {
        olds++;
        news++;
      } else if (p === '-') {
        olds++;
      } else if (p === '+') {
        news++;
      } else {
        fail(`invalid line prefix ${JSON.stringify(p)}`);
      }
    }
    if (lines.length === 0) fail('empty hunk');
    if (olds !== oldLines || news !== newLines) fail('line counts disagree with lines');

    // 0-based position in a where the hunk's old range begins.
    const pos = oldLines === 0 ? oldStart : oldStart - 1;
    if (pos < 0) fail('oldStart out of range');
    if (pos < cursor) fail('hunks overlap or are out of order');
    if (pos + oldLines > a.length) fail('old range exceeds input');

    // Retain unmentioned lines before the hunk; then new coordinates must match.
    for (let i = cursor; i < pos; i++) out.push(a[i]);
    const expectedNewStart = newLines === 0 ? out.length : out.length + 1;
    if (newStart !== expectedNewStart) {
      fail(`newStart ${newStart} disagrees with expected ${expectedNewStart}`);
    }

    let i = pos;
    for (const l of lines) {
      const text = l.slice(1);
      if (l[0] === '+') {
        out.push(text);
        continue;
      }
      if (a[i] !== text) fail(`line ${i + 1} mismatch`);
      if (l[0] === ' ') out.push(text);
      i++;
    }
    cursor = i;
  }

  for (let i = cursor; i < a.length; i++) out.push(a[i]);
  return out;
}

module.exports = { diffLines, unifiedHunks, applyHunks };

'use strict';
const assert = require('node:assert/strict');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  return dp[0][0];
}
let seed = 1;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
const alpha = ['', 'x', 'y', '-z', '+w', ' v'];
const gen = () => Array.from({ length: rnd(15) }, () => alpha[rnd(alpha.length)]);

for (let t = 0; t < 20000; t++) {
  const a = gen(), b = gen();
  const ac = a.slice(), bc = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  const ch = s.filter((e) => e.op !== 'equal').length;
  assert.equal(ch, a.length + b.length - 2 * lcs(a, b));
  for (let i = 1; i < s.length; i++) assert.ok(!(s[i - 1].op === 'insert' && s[i].op === 'delete'));
  assert.deepEqual(diffLines(a, b), s);
  for (const context of [0, 1, 2, 3]) {
    const h = unifiedHunks(a, b, { context });
    if (ch === 0) assert.deepEqual(h, []);
    assert.deepEqual(applyHunks(a, h), b);
  }
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
}
// mismatch
assert.throws(() => applyHunks(['q'], unifiedHunks(['a'], ['b'])), /hunk 0 does not apply/);

// perf
const big = Array.from({ length: 20000 }, (_, i) => (i % 7 === 0 ? '}' : 'line ' + (i % 50)));
const big2 = big.slice(); big2.splice(100, 2, 'X'); big2.splice(10000, 0, 'Y', 'Z'); big2[19990] = 'W';
let t0 = Date.now();
const hs = unifiedHunks(big, big2);
assert.deepEqual(applyHunks(big, hs), big2);
console.log('perf ms', Date.now() - t0, hs.length);
t0 = Date.now();
diffLines(big, big.slice());
console.log('identical ms', Date.now() - t0);
const rep = Array(20000).fill('a'); const rep2 = Array(20000).fill('a'); rep2.splice(5000, 3); rep2.push('b');
t0 = Date.now(); assert.deepEqual(applyHunks(rep, unifiedHunks(rep, rep2)), rep2);
console.log('repetitive ms', Date.now() - t0);
console.log('ok');

